const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Define the state of Arizona
    const states = ee.FeatureCollection('USGS/KATAL/US_STATES_5M');
    const arizona = states.filter(ee.Filter.eq('NAME', 'Arizona'));
    if (arizona.size().getInfo() === 0) {
      console.log("Error: Could not find Arizona boundary.");
      console.log("D"); // Data/boundary error
      return;
    }
    const geometry = arizona.geometry();

    // Define periods
    const targetStartDate = '2017-07-15';
    const targetEndDate = '2017-07-21'; // Modis 8-day composite will span this.
                                        // We filter for images that overlap.
    const histStartYear = 2001;
    const histEndYear = 2010;

    // A robust way to filter for the relevant 8-day composite for a specific week:
    // MODIS 8-day composites start on day of year 1, 9, 17, 25, ...
    // July 15-21 (DOY 196-202). The 8-day period covering this would typically be DOY 193-200.
    // Let's filter for images whose 8-day period overlaps.
    const getModisLST = (year, month, day) => {
      const date = ee.Date.fromYMD(year, month, day);
      // Determine the start of the 8-day composite period that includes 'date'.
      // An 8-day composite starts on day 1, 9, 17, ...
      const doy = date.getRelative('day', 'year').add(1);
      const compositeStartDoy = doy.subtract(1).divide(8).floor().multiply(8).add(1);
      const compositeStartDate = ee.Date.fromYMD(year, 1, 1).advance(compositeStartDoy.subtract(1), 'day');
      const compositeEndDate = compositeStartDate.advance(8, 'day').advance(-1, 'day'); // End of the 8-day period

      // Filter the collection for this specific 8-day composite.
      return ee.ImageCollection('MODIS/051/MYD11A2')
        .filterDate(compositeStartDate, compositeEndDate.advance(1, 'day')) // Filter for images whose 8-day period is this one.
        .first(); // Should be only one 8-day composite for a specific start date.
    };

    // Quality mask for MODIS LST (MYD11A2)
    const applyLSTMask = (image) => {
      if (!image) return null; // Handle null image if no image found for period

      const qc = image.select('QC_Day');
      // LST Quality (bits 0-1): 0 = Good quality, 1 = Retrieved with average quality
      // Cloud Cover (bits 6-7): 0 = Clear sky
      // We want Good quality (0) and Clear sky (0).
      // (qc & 0b00000011) == 0  -> LST Quality bits are 00
      // (qc & 0b11000000) == 0  -> Cloud Cover bits are 00
      const goodQualityAndClear = qc.bitwiseAnd(ee.Number(0b11000011)).eq(0);

      // Select the LST band, scale, and convert to Celsius.
      // LST_Day_1km (scaled by 0.02, in Kelvin)
      const lst = image.select('LST_Day_1km').multiply(0.02).subtract(273.15); // Convert to Celsius

      return lst.updateMask(goodQualityAndClear);
    };

    // 2. Data Acquisition & Check for 2017
    let img2017 = getModisLST(2017, 7, 18); // Use a central date to identify the 8-day composite
    if (!img2017) {
      console.log("2017 Images: 0");
      console.log("C1");
      return;
    }
    img2017 = applyLSTMask(img2017);

    // Get pixel count for 2017 after masking
    let count2017 = img2017.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000, // MODIS resolution is 1km
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();
    if (count2017 === null || count2017 === 0) {
      console.log(`2017 Images: 1 (Valid Pixels: ${count2017})`);
      console.log("C2");
      return;
    }

    // Calculate mean LST for 2017
    const mean2017 = img2017.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    if (mean2017 === null || isNaN(mean2017)) {
      console.log(`2017 LST: ${mean2017}, Pixels: ${count2017}`);
      console.log("C3");
      return;
    }

    // 3. Data Acquisition & Check for historical average
    let historicalImages = ee.ImageCollection([]);
    for (let year = histStartYear; year <= histEndYear; year++) {
      const img = getModisLST(year, 7, 18);
      if (img) { // Only add if image exists
        historicalImages = historicalImages.merge(ee.ImageCollection([applyLSTMask(img)]));
      }
    }

    const histSize = historicalImages.size().getInfo();
    if (histSize === 0) {
      console.log("Historical Images: 0");
      console.log("C1");
      return;
    }

    // Create a composite (mean) for the historical period
    const histComposite = historicalImages.mean();
    if (histComposite === null) {
      console.log(`Historical Images: ${histSize}`);
      console.log("C3"); // Should not happen if historicalImages is not empty.
      return;
    }

    // Get pixel count for historical composite after masking
    const countHist = histComposite.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    if (countHist === null || countHist === 0) {
      console.log(`Historical Images: ${histSize} (Valid Pixels: ${countHist})`);
      console.log("C2");
      return;
    }

    // Calculate mean LST for historical period
    const meanHist = histComposite.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    if (meanHist === null || isNaN(meanHist)) {
      console.log(`Historical LST: ${meanHist}, Pixels: ${countHist}`);
      console.log("C3");
      return;
    }

    // 5. Validation & Final Answer
    console.log(`2017 LST (C): ${mean2017.toFixed(2)}, Pixels: ${count2017}`);
    console.log(`2001-2010 Avg LST (C): ${meanHist.toFixed(2)}, Pixels: ${countHist}`);

    if (mean2017 > meanHist) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.log("An unexpected error occurred:", error);
    console.log("D"); // Catch-all for other errors
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

